import pathlib,json,hashlib,urllib.request,urllib.parse,pypdf
from shapely.geometry import Polygon
P=pathlib.Path(__file__).parent
D=[('miami','miami-1994','mia-old',[[99,113],[127,113],[130,125],[143,110],[218,107],[236,115],[251,132],[260,155],[260,178],[252,197],[234,209],[201,216],[148,216],[123,209],[103,194]],'https://www.barkerpacific.com/commercial-projects/miami-arena'),('orlando','orlando-west-1995','orl-old',[[87,90],[268,90],[268,218],[87,218]],'https://orlando.novusagenda.com/AgendaPublic/AttachmentViewer.ashx?AttachmentID=70311&ItemID=41659')]
for short,name,aid,px,identity in D:
 pg=pypdf.PdfReader(P/('usgs-'+name+'.pdf')).pages[0];L=pg['/LGIDict'][0];H=float(pg.mediabox.height);ctm=list(map(float,L['/CTM']));m=json.loads((P/('usgs-'+name+'-crop-location.json')).read_text());rr=json.loads((P/('usgs-'+name+'-roof-render.json')).read_text());x0,y0=rr['clipPdfTopLeft'][:2];sc=rr['scale'];poly=Polygon([(x0+x/sc,H-(y0+y/sc))for x,y in px]);pts=[[poly.centroid.x,poly.centroid.y]]+list(map(list,poly.exterior.coords));a,b,c,d,e,f=ctm
 neat=list(map(float,L['/Neatline']));control=[neat[i:i+2]for i in [0,6,12,18]];inputs=pts+control
 geo=[{'x':a*x+c*y+e,'y':b*x+d*y+f}for x,y in inputs]
 u='https://utility.arcgisonline.com/ArcGIS/rest/services/Geometry/GeometryServer/project?'+urllib.parse.urlencode({'inSR':json.dumps({'wkt':m['sourceWkt']}),'outSR':4326,'geometries':json.dumps({'geometryType':'esriGeometryPoint','geometries':geo}),'f':'json'})
 with urllib.request.urlopen(u,timeout=60)as r:body=r.read()
 out=json.loads(body);(P/(short+'-roof-reprojection.json')).write_bytes(body);pt=out['geometries'][0];sm=json.loads((P/('usgs-'+name+'-metadata.json')).read_text())
 o={'arenaId':aid,'latitude':pt['y'],'longitude':pt['x'],'status':'primary-usgs-historical-roof-map-symbol-centroid-derived','pointMeaning':'area centroid of manually traced original historical USGS building symbol; mapped site point, not surveyed court center','sourceUrl':sm['url'],'sourcePath':sm['path'],'sourceBodySha256':sm['bodySha256'],'bodySha256':sm['bodySha256'],'renderPath':'usgs-'+name+'-roof-detail.png','renderClipPdfTopLeft':rr['clipPdfTopLeft'],'renderScale':sc,'tracedImageVertices':px,'pdfVertices':list(map(list,poly.exterior.coords)),'pdfCentroid':pts[0],'mapCTM':ctm,'sourceWkt':m['sourceWkt'],'projectionRequestUrl':u,'projectionResponsePath':short+'-roof-reprojection.json','projectionResponseSha256':hashlib.sha256(body).hexdigest(),'transformedVerticesWgs84':out['geometries'][1:1+len(poly.exterior.coords)],'neatlineControls':{'pdfPoints':control,'transformedWgs84':out['geometries'][-4:]},'derivation':'shoelace area centroid in PDF plane; GeoPDF CTM to map meters; NAD83 Transverse Mercator to WGS84 using original ArcGIS GeometryServer. Four neatline corner controls retained.','identityPrimarySources':[identity],'uncertainty':'Manually traced printed building symbol at 1:24000; practical accuracy tens of meters. Miami original USGS map explicitly labels Miami Arena; Orlando footprint is on the former arena parcel west of I-4 at Amelia, corroborated by municipal former-site records. No court-center precision claim.'}
